#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url "media/tone48k-stereo.wav"
    loop TRUE
    startTime 946684800.048
  }
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 89

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

DEF K Script {
  initializeOnly SFNode  o USE O
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 89

  url "javascript:
function set_time (value) { ++ n;
   if (n === 20) { o.gain = 0.25; }
   if (n === 26) { o.gain = 0; }
   if (n === 32) { o.gain = 3; }
   if (n === 38) { o.gain = -1; }
   if (n === 44) { o.gain = 1; }
}
"
  directOutput TRUE
}

ROUTE T.time TO S.set_time
ROUTE S.start TO O.set_startTime
ROUTE T.time TO K.set_time
